const relation=(from,sea)=>{if(sea==null)return'Not applicable';const a=diff(from,sea);return a<=45?'Onshore':a<90?'Cross-onshore':a<135?'Cross-offshore':'Offshore'};
function rnliPatrolState(s,at=new Date()){let r=s.rnli;if(!r?.start||!r?.end)return{active:false,label:r?'Check current flags':'No verified patrol data'};let day=at.toISOString().slice(0,10),hour=at.getHours(),active=day>=r.start&&day<=r.end&&hour>=(r.hours?.[0]??0)&&hour<(r.hours?.[1]??24);return{active,label:active?'RNLI patrol scheduled now — confirm flags':day<r.start?'RNLI season has not started':'Outside verified RNLI patrol dates'}}
