function drawWindAtLaunch(){if(!map||!state.live)return;let s=spots[state.spot],d=state.live,html=`<div class="launch-wind" style="--wind:${(d.dir+180)%360}deg"><i>↑</i><b>${Math.round(d.wind)}</b><small>mph from ${compass(d.dir)}</small></div>`;if(windMarker)windMarker.remove();windMarker=L.marker([s.lat,s.lon],{icon:L.divIcon({className:'',html,iconSize:[76,76],iconAnchor:[38,38]}),zIndexOffset:1000}).addTo(map)}
