async function updateMapSignals(){if(!map)return;let entries=Object.entries(spots),lat=entries.map(([,s])=>s.lat).join(','),lon=entries.map(([,s])=>s.lon).join(','),future=Boolean(state.selectedTime);try{let endpoint=future?`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&hourly=wind_speed_10m,wind_direction_10m,wind_gusts_10m&forecast_days=7&timezone=Europe%2FLondon&wind_speed_unit=mph`:`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=wind_speed_10m,wind_direction_10m,wind_gusts_10m&wind_speed_unit=mph`,r=await fetch(endpoint),rows=await r.json();if(!Array.isArray(rows))rows=[rows];rows.forEach((x,i)=>{let [id,s]=entries[i],at=future?x.hourly?.time?.indexOf(state.selectedTime):-1,d=future&&at>=0?{wind:+x.hourly.wind_speed_10m[at],gust:+x.hourly.wind_gusts_10m[at],dir:+x.hourly.wind_direction_10m[at]}:{wind:+x.current?.wind_speed_10m,gust:+x.current?.wind_gusts_10m,dir:+x.current?.wind_direction_10m};if(!Number.isFinite(d.wind))return;let colour=signalFor(s,d);s._signal=colour;markers[id]?.setIcon(markerIcon(colour))});mapCard(state.spot,spots[state.spot]._signal||'grey')}catch(e){}}
