async function enrichMarine(){let s=spots[state.spot],box=$('#marineReadout');state.marine=null;if(!['coast','harbour','estuary'].includes(s.type)){box.innerHTML='<span>WATER MOVEMENT</span><strong>Gauge connection is the next data step</strong><small>Rainfall remains a warning proxy. Until a local safe range is validated, a river level must be information—not a green light.</small>';return}try{let r=await fetch(`https://marine-api.open-meteo.com/v1/marine?latitude=${s.lat}&longitude=${s.lon}&current=wave_height,wave_direction,wave_period,swell_wave_height,swell_wave_direction,swell_wave_period,ocean_current_velocity,ocean_current_direction&hourly=sea_level_height_msl&forecast_days=2&timezone=Europe%2FLondon&cell_selection=sea&wind_speed_unit=kn`),x=await r.json(),levels=x.hourly?.sea_level_height_msl||[],times=x.hourly?.time||[],turns=[];for(let i=1;i<levels.length-1;i++)if((levels[i]>=levels[i-1]&&levels[i]>levels[i+1])||(levels[i]<=levels[i-1]&&levels[i]<levels[i+1]))turns.push({high:levels[i]>levels[i-1],time:times[i]});let next=turns.filter(t=>new Date(t.time)>new Date()).slice(0,2).map(t=>`${t.high?'High':'Low'} ${time(t.time)}`).join(' · '),c=x.current||{},sea=c.wave_height==null?'Wave model unavailable':`${c.wave_height.toFixed(1)} m sea from ${compass(c.wave_direction)} · ${Math.round(c.wave_period||0)} sec`,swell=c.swell_wave_height==null?'swell split unavailable':`${c.swell_wave_height.toFixed(1)} m swell from ${compass(c.swell_wave_direction)} · ${Math.round(c.swell_wave_period||0)} sec`,current=c.ocean_current_velocity==null?'broad current unavailable':`${c.ocean_current_velocity.toFixed(1)} kn toward ${compass(c.ocean_current_direction)}`;state.marine={swellHeight:c.swell_wave_height,swellDir:c.swell_wave_direction,swellPeriod:c.swell_wave_period,currentSpeed:c.ocean_current_velocity,currentDir:c.ocean_current_direction};box.innerHTML=`<span>SURF / CHARGER PULSE</span><strong>${sea}</strong><small>${swell} · ${current}<br>${next||'Next tide turns unavailable'} · Current is an ~8 km model, not harbour, estuary or navigation advice.</small>`;render()}catch{box.innerHTML='<span>SURF / CHARGER PULSE</span><strong>Marine feed unavailable</strong><small>Check a local tide table and observation before travel.</small>'}}
async function loadMarineOverlay(){let s=spots[state.spot];if(waveMarker){waveMarker.remove();waveMarker=null}if(!map||!['coast','harbour','estuary'].includes(s.type))return;try{let r=await fetch(`https://marine-api.open-meteo.com/v1/marine?latitude=${s.lat}&longitude=${s.lon}&current=wave_height,wave_direction,wave_period&hourly=sea_level_height_msl&forecast_days=1&timezone=Europe%2FLondon&cell_selection=sea`),x=await r.json(),h=x.current?.wave_height,dir=x.current?.wave_direction,levels=x.hourly?.sea_level_height_msl||[],times=x.hourly?.time||[],now=Date.now(),i=times.reduce((b,t,n)=>Math.abs(new Date(t)-now)<Math.abs(new Date(times[b])-now)?n:b,0),trend=i>0?levels[i]-levels[i-1]:0,tide=trend>.02?'TIDE ↑':trend<-.02?'TIDE ↓':'TIDE TURN',html=`<div class="wave-marker" style="--wave:${dir||0}deg"><i>↑</i><b>${h==null?'SEA':h.toFixed(1)+'m WAVE'}</b><small>${dir==null?'direction unavailable':`from ${compass(dir)}`} · ${tide}</small></div>`;waveMarker=L.marker([s.lat,s.lon],{icon:L.divIcon({className:'',html,iconSize:[120,54],iconAnchor:[-42,27]}),zIndexOffset:900}).addTo(map)}catch{}}
const originalLoad=load;
