const windGrid=[[-8,50],[-5,50],[-2,50],[1,50],[-8,52],[-5,52],[-2,52],[1,52],[-8,54],[-5,54],[-2,54],[1,54],[-8,56],[-5,56],[-2,56],[1,56],[-8,58],[-5,58],[-2,58],[1,58],[-8,60],[-5,60],[-2,60],[1,60]];
