async function loadWindField(){try{let lat=windGrid.map(p=>p[1]).join(','),lon=windGrid.map(p=>p[0]).join(','),r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=wind_speed_10m,wind_direction_10m&wind_speed_unit=mph`),rows=await r.json();if(!Array.isArray(rows))rows=[rows];windSamples=rows.map((x,i)=>({lon:windGrid[i][0],lat:windGrid[i][1],speed:+x.current.wind_speed_10m,dir:+x.current.wind_direction_10m}));startWindField()}catch{}}
function startWindField(){let c=$('#windField'),ctx=c.getContext('2d'),stage=c.parentElement,resize=()=>{c.width=stage.clientWidth*devicePixelRatio;c.height=stage.clientHeight*devicePixelRatio;c.style.width=stage.clientWidth+'px';c.style.height=stage.clientHeight+'px';ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);flowParticles=Array.from({length:120},()=>({x:Math.random()*stage.clientWidth,y:Math.random()*stage.clientHeight,age:Math.random()*70}))};resize();addEventListener('resize',resize);function frame(){let w=stage.clientWidth,h=stage.clientHeight;ctx.globalCompositeOperation='destination-out';ctx.fillStyle='rgba(0,0,0,.2)';ctx.fillRect(0,0,w,h);ctx.globalCompositeOperation='source-over';ctx.lineWidth=1.35;flowParticles.forEach(p=>{let ll=map.containerPointToLatLng([p.x,p.y]),v=windSamples.reduce((a,b)=>(Math.abs(b.lat-ll.lat)+Math.abs(b.lon-ll.lng))<(Math.abs(a.lat-ll.lat)+Math.abs(a.lon-ll.lng))?b:a),rad=(v.dir+90)*Math.PI/180,step=.28+v.speed/22,nx=p.x+Math.cos(rad)*step,ny=p.y+Math.sin(rad)*step;ctx.strokeStyle=`rgba(4,91,108,${.38+Math.min(.42,v.speed/55)})`;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(nx,ny);ctx.stroke();p.x=nx;p.y=ny;p.age++;if(p.x<0||p.x>w||p.y<0||p.y>h||p.age>85){p.x=Math.random()*w;p.y=Math.random()*h;p.age=0}});requestAnimationFrame(frame)}requestAnimationFrame(frame)}
loadWindField();

const originalMapCard=mapCard;
mapCard=function(id,colour){originalMapCard(id,colour);let s=spots[id],badge=$('#evidenceBadge'),link=$('#evidenceLink');badge.textContent=s.evidence?`✓ ${s.evidence.toUpperCase()}`:s.source?'◐ PUBLISHED SOURCE':'◌ LOCAL DETAIL TO VERIFY';badge.className=s.evidence?'verified':s.source?'sourced':'lead';link.hidden=!s.source;if(s.source)link.href=s.source};
if(state.spot)mapCard(state.spot,spots[state.spot]._signal||'grey');
const renderEvidence=render;
render=function(){renderEvidence();let s=spots[state.spot],target=Object.values(spots).find(x=>x.name===s.alt),strong=$('.alt-score strong'),small=$('.alt-score small'),tips={sup:'Stay within a distance you could genuinely swim. If wind wins, lie prone, secure the paddle under your chest and paddle across the wind toward the nearest safe shore.',windsurf:'Check the downwind landing before rigging. If you cannot identify a safe exit, the session has no proper Plan B.',wing:'Carry a board leash, wing leash and means of communication. Know how you will self-rescue with the wing depowered before launching.',kite:'Confirm a clear launch, landing and downwind exclusion zone. A green wind reading cannot make a cramped beach suitable for a kite.'};$('#buddyTip').textContent=tips[state.sport];if(target&&(target.evidence||target.source)){strong.textContent='Evidence-backed alternative';small.textContent=target.evidence||'Published location source available'}else{strong.textContent='Alternative needs verification';small.textContent='Weather comparison only — confirm access and sport use'}};
