// Curated hazards are independent of broad forecast models. "Extreme" blocks a green
// beginner signal; hazard-only pins are never suggested as launches.
const forecastSignalFor=signalFor;
signalFor=function(s,d){if(s.hazardOnly)return'red';let result=forecastSignalFor(s,d);if(s.hazard?.severity==='extreme'&&state.skill!=='advanced')return'red';if(s.hazard?.severity==='high'&&result==='green')return'amber';return result};
const forecastRisk=risk;
risk=function(){let s=spots[state.spot];if(s?.hazardOnly)return'red';let result=forecastRisk();if(s?.hazard?.severity==='extreme'&&state.skill!=='advanced')return'red';if(s?.hazard?.severity==='high'&&result==='green')return'amber';return result};
const forecastWords=words;
words=function(level){let s=spots[state.spot],h=s?.hazard;if(s?.hazardOnly)return{label:'Hazard reference — do not launch',title:h.title,copy:h.copy,advice:'Use the source link and seek qualified local guidance. Shorewise will not turn model weather into a go signal here.'};if(h?.severity==='extreme'&&state.skill!=='advanced')return{label:'Local hazard overrides forecast',title:h.title,copy:h.copy,advice:'Choose a different water or go with a qualified local provider. A favourable wind colour is not enough.'};return forecastWords(level)};
const evidenceMapCard=mapCard;
mapCard=function(id,colour){evidenceMapCard(id,colour);let s=spots[id],h=s.hazard,card=$('#hazardCard');if(s.hazardOnly){$('#mapType').textContent=`${s.region||''} · HAZARD REFERENCE`.toUpperCase();$('#mapSignal').textContent='Never auto-recommended';$('#sessionIdea').innerHTML='<span>SAFER PLAN</span><strong>Choose a different venue</strong><small>This pin exists to warn you, not to advertise a launch or route.</small>'}card.hidden=!h;if(!h)return;card.className=`hazard-card ${h.severity==='extreme'?'severe':''}`;$('#hazardTitle').textContent=h.title;$('#hazardCopy').textContent=h.copy;$('#hazardLink').href=h.source||s.source||'#'};
