$('#mapInfoToggle').onclick=()=>{let stage=$('.map-stage'),hidden=stage.classList.toggle('card-hidden'),button=$('#mapInfoToggle');button.textContent=hidden?'Show spot card':'Hide spot card';button.setAttribute('aria-expanded',String(!hidden));setTimeout(()=>map?.invalidateSize(),220)};

let smartAlternativeId=null;
function milesBetween(a,b){const r=3958.8,p=Math.PI/180,dLat=(b.lat-a.lat)*p,dLon=(b.lon-a.lon)*p,x=Math.sin(dLat/2)**2+Math.cos(a.lat*p)*Math.cos(b.lat*p)*Math.sin(dLon/2)**2;return 2*r*Math.asin(Math.sqrt(x))}
function exposureOf(s){if(Number.isFinite(s.exposure))return s.exposure;if(['lake','reservoir','river'].includes(s.type))return 0;if(['harbour','estuary'].includes(s.type))return 1;return 3}
function isSupSurfProfile(){return state.sport==='sup'&&(state.planSupUse||state.profile?.supDiscipline)==='surf'}
const roadCache=new Map(),roadPending=new Set();
function smartAlternative(){
  let here=spots[state.spot],live=state.live,named=Object.entries(spots).find(([,s])=>s.name===here.alt)?.[0],hereExposure=exposureOf(here),local=new Map((here.localAlternatives?.[state.sport]||[]).map(x=>[x.id,x]));
  let candidates=Object.entries(spots)
    .filter(([id,s])=>id!==state.spot&&s.sports?.includes(state.sport)&&(s.evidence||s.source)&&!s.hazardOnly&&(!isSupSurfProfile()||s.type==='coast'&&s.supUses?.includes('surf')))
    .map(([id,s])=>{
      let distance=milesBetween(here,s),signal=s._signal||(live?signalFor(s,live):'grey'),localRule=local.get(id),distanceScore=distance<=15?65:distance<=30?42:distance<=50?15:-80,score=(signal==='green'?80:signal==='amber'?43:signal==='grey'?18:-25)+distanceScore;
      score+=s.evidence?13:6;
      if(id===named&&distance<=50)score+=12;
      if(localRule)score+=localRule.priority||20;
      if(live?.wave>=1.2&&exposureOf(s)<hereExposure)score+=(hereExposure-exposureOf(s))*18;
      if(state.skill==='beginner'&&exposureOf(s)>=3)score-=18;
      if(state.sport==='sup'&&!isSupSurfProfile()&&['lake','reservoir'].includes(s.type)&&s.evidence)score+=8;
      if(s.type==='river')score-=riverRainRisk(live)===2?120:riverRainRisk(live)===1?45:0;
      if(state.sport==='sup'&&state.skill==='beginner'&&rnliPatrolState(s).active)score+=18;
      return{id,s,distance,signal,score,distanceScore,minutes:localRule?.minutes,note:localRule?.note};
    })
    .filter(x=>x.distance<=50&&(x.signal!=='red'||state.sport==='sup'&&['lake','reservoir'].includes(x.s.type)))
    .sort((a,b)=>b.score-a.score);
  let winner=candidates[0]||null;if(winner)winner.shortlist=candidates.slice(0,5);return winner;
}
function flatWaterPlanB(){if(!isSupSurfProfile())return null;let here=spots[state.spot];return Object.entries(spots).filter(([id,s])=>id!==state.spot&&!s.hazardOnly&&s.sports?.includes('sup')&&(s.evidence||s.source)&&(s.supUses?.includes('touring')||['lake','reservoir','river'].includes(s.type))).map(([id,s])=>({id,s,distance:milesBetween(here,s),signal:s._signal||(state.live?signalFor(s,state.live):'grey')})).filter(x=>x.distance<=50&&x.signal!=='red').sort((a,b)=>(a.signal==='green'?0:1)-(b.signal==='green'?0:1)||a.distance-b.distance)[0]||null}
function alternativeReason(choice){let here=spots[state.spot],s=choice.s,bits=[];if(state.live){let currentRel=relation(state.live.dir,here.sea),nextRel=relation(state.live.dir,s.sea);if(['Offshore','Cross-offshore'].includes(currentRel)&&!['Offshore','Cross-offshore'].includes(nextRel))bits.push('safer wind angle');if(state.live.wave>=1.2&&exposureOf(s)<exposureOf(here))bits.push('more shelter from swell')}if(['lake','reservoir'].includes(s.type)&&['coast','harbour','estuary'].includes(here.type))bits.push('managed inland fallback');if(s.type==='river')bits.push(riverRainRisk(state.live)?'recent rain may mean more flow':'low modelled rain over three days');if(s.evidence)bits.push('documented local use');else bits.push('published location source');let journey=Number.isFinite(choice.minutes)?`about ${choice.minutes} min drive`:'road time not checked';return `${journey} · ${bits.slice(0,2).join(' · ')||choice.note||'different launch orientation'}`}
function roadKey(){return`${state.spot}|${state.sport}|${state.skill}|${state.planSupUse||state.profile?.supDiscipline||''}|${state.selectedTime||'now'}`}
async function refineRoadAlternative(shortlist,key){if(!shortlist?.length||roadPending.has(key))return;roadPending.add(key);let here=spots[state.spot],coords=[[here.lon,here.lat],...shortlist.map(x=>[x.s.lon,x.s.lat])].map(x=>x.join(',')).join(';'),destinations=shortlist.map((_,i)=>i+1).join(';');try{let response=await fetch(`https://router.project-osrm.org/table/v1/driving/${coords}?sources=0&destinations=${destinations}`),json=await response.json(),durations=json?.durations?.[0]||[];let routed=shortlist.map((choice,i)=>({...choice,minutes:Number.isFinite(durations[i])?Math.round(durations[i]/60):choice.minutes})).filter(choice=>Number.isFinite(choice.minutes)&&choice.minutes<=60).map(choice=>({...choice,roadScore:choice.score-choice.distanceScore+(choice.minutes<=20?65:choice.minutes<=40?42:15)})).sort((a,b)=>b.roadScore-a.roadScore);roadCache.set(key,routed[0]||null)}catch(error){roadCache.set(key,null)}finally{roadPending.delete(key);if(key===roadKey())paintAlternative(roadCache.get(key),false,true)}}
function arrivalTip(){let s=spots[state.spot],d=state.live;if(d&&['Offshore','Cross-offshore'].includes(d.angle))return'Offshore wind? Don’t launch. Find a shore where it blows in or across.';if(s.type==='river')return'Fast flow, debris or rising water? Walk away.';if(s.type==='coast'&&d?.wave>=1)return'Watch three full sets. Find rips, rocks and a second exit.';if(state.sport==='sup')return'Stay within swimming distance. Blown away? Lie down and paddle diagonally to shore.';return'Before rigging, find your downwind exit.'}
let flatWaterPlanBId=null;
function paintAlternative(choice,pending=false,routeChecked=false,planB=flatWaterPlanB()){let strong=$('.alt-score strong'),small=$('.alt-score small'),orb=$('.mini-orb'),plan=$('#sessionPlanB');smartAlternativeId=choice?.id||null;flatWaterPlanBId=planB?.id||null;$('#buddyTip').textContent=arrivalTip();plan.hidden=!planB;if(planB){$('#planBName').textContent=planB.s.name;$('#planBMeta').textContent=`${Math.round(planB.distance)} miles away · a separate flat-water option, subject to access and on-arrival checks`;}if(!choice){$('#altName').textContent=isSupSurfProfile()?'No credible SUP-surf match nearby':'No credible match within about an hour';$('#altMeta').textContent=isSupSurfProfile()?'No documented wave spot currently fits this profile and forecast within about an hour':routeChecked?'No road-time-qualified alternative found':'Check the map manually or change sport/profile';strong.textContent=isSupSurfProfile()?'No surf recommendation':'No automatic redirect';small.textContent=isSupSurfProfile()?'Flat water may still be possible, but it is not being presented as SUP surfing.':'A distant famous venue is not being presented as “nearby”';orb.textContent='—';return}$('#altName').textContent=choice.s.name;$('#altMeta').textContent=pending?'Checking actual road time…':alternativeReason(choice);strong.textContent=choice.signal==='green'?'Stronger local match for this profile':choice.signal==='red'?'Not recommended in this wind':'Local option worth comparing';small.textContent=choice.s.intel||choice.s.access;orb.textContent=pending?'…':choice.signal==='green'?'✓':'!'}
function renderSmartAlternative(){let key=roadKey(),choice=smartAlternative(),planB=flatWaterPlanB();if(roadCache.has(key)){paintAlternative(roadCache.get(key),false,true,planB);return}paintAlternative(choice,Boolean(choice),false,planB);if(choice)refineRoadAlternative(choice.shortlist,key)}
const renderAlternatives=render;
render=function(){renderAlternatives();renderSmartAlternative()};
$('#routeButton').onclick=()=>{if(!smartAlternativeId)return toast('No evidence-backed nearby match for this sport and profile');chooseFromMap(smartAlternativeId);document.querySelector('.map-panel')?.scrollIntoView({behavior:'smooth',block:'start'})};
$('#planBButton').onclick=()=>{if(!flatWaterPlanBId)return;chooseFromMap(flatWaterPlanBId);toast('Showing a separate flat-water Plan B — not a SUP-surf recommendation.');document.querySelector('.map-panel')?.scrollIntoView({behavior:'smooth',block:'start'})};
