function renderReadiness(sport=state.freeSport||'sup'){let config=readiness[sport]||readiness.sup,profile=state.profile||{},chosen=new Set(profile.readiness||[]);$('#sportKit').innerHTML=config.kit.map(([value,label])=>`<label><input type="checkbox" name="readiness" value="${value}" ${chosen.has(value)?'checked':''}><span>${label}</span></label>`).join('');$('#sportCapability').innerHTML=config.ability.map(([value,label])=>`<label><input type="checkbox" name="readiness" value="${value}" ${chosen.has(value)?'checked':''}><span>${label}</span></label>`).join('');$('#qualificationSelect').innerHTML=config.awards.map(([value,label])=>`<option value="${value}" ${profile.qualification===value?'selected':''}>${label}</option>`).join('')}
async function locateHome(query){let response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=gb,ie&q=${encodeURIComponent(query)}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Location lookup failed');let result=(await response.json())[0];if(!result)throw new Error('Area not found');return{label:result.display_name.split(',').slice(0,2).join(', '),lat:+result.lat,lon:+result.lon}}

async function calculateDriveTimes(home){let candidates=Object.entries(spots).filter(([,s])=>Number.isFinite(s.lat)&&Number.isFinite(s.lon)&&milesBetween(home,s)<=ROUTING_PREFILTER_MILES),driveMinutes={},batchSize=18;for(let start=0;start<candidates.length;start+=batchSize){let batch=candidates.slice(start,start+batchSize),coords=[[home.lon,home.lat],...batch.map(([,s])=>[s.lon,s.lat])].map(pair=>pair.join(',')).join(';'),destinations=batch.map((_,i)=>i+1).join(';'),url=`https://router.project-osrm.org/table/v1/driving/${coords}?sources=0&destinations=${destinations}`;let response=await fetch(url);if(!response.ok)throw new Error('Drive-time lookup failed');let data=await response.json(),durations=data.durations?.[0]||[];batch.forEach(([id],i)=>{let seconds=durations[i];if(Number.isFinite(seconds))driveMinutes[id]=Math.round(seconds/60)})}return driveMinutes}

