function inFreeArea(s,id){if(!state.home)return true;let routed=state.home.driveMinutes?.[id];if(Number.isFinite(routed))return routed<=FREE_DRIVE_MINUTES;return milesBetween(state.home,s)<=35}
function applyProfileMapFilter(){if(!map)return;let premium=state.plan==='premium';Object.entries(spots).forEach(([id,s])=>{let visible=premium||((s.hazardOnly||!s.sports||s.sports.includes(state.freeSport))&&inFreeArea(s,id)),marker=markers[id];if(!marker)return;if(visible&&!map.hasLayer(marker))marker.addTo(map);else if(!visible&&map.hasLayer(marker))marker.removeFrom(map)});$$('#spotSelect option').forEach(option=>{if(!option.value)return;let s=spots[option.value],suitable=premium||!s?.sports||s.sports.includes(state.freeSport);option.hidden=option.disabled=Boolean(s&&(!premium&&(!inFreeArea(s,option.value)||!suitable)))})}
