save=async function(){let form=$('#setupForm');if(!form.reportValidity())return;let f=new FormData(form),sport=f.get('primary_sport')||'sup',skill=f.get('profile_skill')||'beginner',query=String(f.get('home_area')||'').trim(),dialog=$('#setupDialog');dialog.classList.add('setup-busy');$('#homeAreaError').hidden=true;try{let home=state.home?.query===query?state.home:await locateHome(query);home.query=query;try{home.driveMinutes=await calculateDriveTimes(home);home.routing='road-time'}catch(routingError){home.driveMinutes={};home.routing='straight-line fallback'}state.home=home;state.freeSport=sport;state.sport=sport;state.mode=sport==='sup'?'paddle':'wind';state.skills[sport]=skill;state.skill=skill;state.profile={readiness:f.getAll('readiness'),qualification:f.get('qualification')||'none',supDiscipline:f.get('sup_discipline')||'touring',boardType:f.get('board_type')||'inflatable',termsVersion:TERMS_VERSION,acceptedAt:new Date().toISOString(),ackInitials:String(f.get('ack_initials')||'').trim().toUpperCase()};localStorage.setItem('shorewise-profile-v6',JSON.stringify({freeSport:sport,skills:state.skills,profile:state.profile,home:state.home,setupComplete:true}));hasSetup=true;dialog.dataset.required='false';dialog.classList.remove('setup-required');dialog.close();updateProfileUI();map?.setView([state.home.lat,state.home.lon],8);if(state.spot&&!inFreeArea(spots[state.spot],state.spot)){state.spot='';state.live=null;$('#spotSelect').value=''}if(state.spot){render();updateMapSignals()}toast(`${profileLabel()} · ${state.home.routing==='road-time'?'within about 60 minutes of':'local area around'} ${state.home.label}`)}catch(error){$('#homeAreaError').hidden=false}finally{dialog.classList.remove('setup-busy')}};
