wales:[['Natural Resources Wales bathing waters','https://naturalresources.wales/guidance-and-advice/environmental-topics/water-management-and-quality/bathing-water-quality/'],['Natural Resources Wales flood warnings','https://flood-warning.naturalresources.wales/']],
ni:[['DAERA bathing-water quality','https://www.daera-ni.gov.uk/topics/water/bathing-water-quality'],['Flood Maps NI','https://www.infrastructure-ni.gov.uk/topics/rivers-and-flooding/flood-maps-ni']],
ireland:[['EPA Beaches.ie water quality','https://www.beaches.ie/'],['OPW river levels','https://waterlevel.ie/']]
