function nationFor(s){let r=(s.region||'').toLowerCase(),lat=s.lat,lon=s.lon;if(r.includes('ireland')&&!r.includes('northern'))return'ireland';if(r.includes('northern ireland')||r==='ni'||lat>54&&lon<-5.2&&lon>-8.3)return'ni';if(r.includes('scot')||lat>55.75&&lon>-8)return'scotland';if(r.includes('wales')||r.includes('welsh')||lat<53.6&&lon<-2.7&&lon>-5.8)return'wales';return'england'}
function renderWaterStatus(s){let nation=nationFor(s),links=officialWaterLinks[nation],coastal=['coast','harbour','estuary'].includes(s.type),river=s.type==='river';$('#waterStatusTitle').textContent=river?'Rain, flow and river checks':coastal?'Pollution and patrol checks':'No universal live water-quality feed';$('#waterStatusCopy').textContent=river?'Shorewise screens one- and three-day modelled rain, but rainfall is only an early warning. At the water, fast or rising flow, brown water and debris override the forecast. Use a quick-release waist leash, buoyancy aid and a buddy.':coastal?'Where an official designated bathing-water alert exists, use it as a warning layer—not proof that an unmonitored beach or river mouth is clean. Check signs and water appearance on arrival.':'Managed venues, councils and operators may publish notices outside national bathing-water systems. No alert never means clean water.';$('#waterStatusLinks').innerHTML=links.map(([label,url])=>`<a href="${url}" target="_blank" rel="noreferrer">${label}<span>↗</span></a>`).join('')+`<span>${river?'Check the live gauge where available; no alert is not a clearance':'Sewage alert matching: planned data integration'}</span>`}

const mateTips={
sup:{beginner:['Stay within a distance you could genuinely swim. A leash keeps the board close; it does not make offshore wind harmless.','Start into the wind where possible, so the easier leg brings you home. If the wind wins, lie prone and paddle diagonally toward the nearest safe shore.','At a lifeguarded beach, ask where the black-and-white watersports zone is. Never launch an inflatable under an orange windsock.'],intermediate:['Before a coastal tour, identify a second landing and the tide state there—not just at the start.','Wind against tide can steepen the water quickly. If the texture changes, shorten the route rather than waiting for the forecast to prove itself.','Watch several wave sets and look for water moving seaward before deciding where to launch.'],advanced:['Clean offshore wind may improve SUP surf, but it also removes the easy return. Only use a documented break, a realistic self-rescue plan and a downwind exit.','Reef and point breaks can change radically with tide. A good swell number does not confirm the entry, exit or crowd situation.','For a downwinder, verify the landing, daylight and transport before treating a favourable wind arrow as a plan.']},
windsurf:{beginner:['Use a recognised teaching or managed-water launch. Begin upwind of your exit and keep enough board volume to uphaul.'],intermediate:['Check the downwind landing before rigging. Cliffs and dunes can leave the launch gusty even when the model looks clean.'],advanced:['Cross-off can produce exceptional waves, but only where the launch, wind line and downwind exit are documented. Buddy sail and check the carry at high tide.']},
wing:{beginner:['Use open space, enough depth and a documented learning launch. Practise the self-rescue before relying on the foil to get home.'],intermediate:['Shallow water can protect a learner but damage a foil. Check depth through the whole launch corridor, not only at the beach.'],advanced:['A foil may hold ground better than a SUP, but offshore wind still demands a downwind exit, reliable board leash and buddy plan.']},
kite:{beginner:['Use a recognised kite beach and school. Do not improvise a solo launch because the wind colour is green.'],intermediate:['Confirm the launch, landing and full downwind exclusion zone. Keep swimmers outside the kite corridor.'],advanced:['Strong wind is not the only test: gust gradient, tide, hard objects and downwind space can make a famous spot unusable.']}
};
function rotatingMateTip(){let sport=state.sport||'sup',skill=state.skill||'beginner',s=spots[state.spot],d=state.live;if(sport==='sup'&&s?.type==='river')return'If the flow is faster than a comfortable walking pace, rising or carrying debris, do not launch. On moving water use a quick-release waist leash, buoyancy aid, a known downstream exit and a buddy.';if(sport==='sup'&&['lake','reservoir'].includes(s?.type))return'Start into the wind and keep to the shore that gives the simplest landing. Turn around before you are tired so the easier leg brings you back.';if(sport==='sup'&&['Offshore','Cross-offshore'].includes(d?.angle))return'If the wind starts winning, kneel first; if necessary lie prone with the paddle secured under your chest and paddle diagonally—not straight upwind—to the nearest workable shore.';let list=mateTips[sport]?.[skill]||mateTips[sport]?.beginner||mateTips.sup.beginner,seed=(state.spot||'home').split('').reduce((a,c)=>a+c.charCodeAt(0),new Date().getDate());return list[seed%list.length]}
const v7Render=render;
render=function(){v7Render();let tip=$('#buddyTip');if(tip)tip.textContent=rotatingMateTip();let headline=$('#sponsorHeadline');if(headline)headline.textContent={sup:'Paddle kit matched to today’s SUP profile',wing:'Wing and foil kit matched to today’s wind range',windsurf:'Sails and boards matched to today’s wind range',kite:'Kite kit matched to today’s documented launch'}[state.sport]||'Relevant kit for today’s profile';if(state.spot)renderWaterStatus(spots[state.spot])};

const v7Risk=risk;
function supSurfWindow(){let s=spots[state.spot],d=state.live,discipline=state.planSupUse||state.profile?.supDiscipline,board=state.profile?.boardType,coastal=s?.type==='coast'&&(!s.sports||s.sports.includes('sup'))&&!s.hazardOnly&&s.windVenue!==false&&s.noSurf!==true;if(state.sport!=='sup'||discipline!=='surf'||board!=='hard'||!coastal||!d)return false;let limits=state.skill==='beginner'?{wind:8,wave:1,period:8}:state.skill==='intermediate'?{wind:15,wave:2,period:7}:{wind:25,wave:3,period:6};return d.wind<=limits.wind&&d.wave>=.3&&d.wave<=limits.wave&&(d.period||0)>=limits.period&&d.gust-d.wind<12}
