const v7Words=words;
words=function(level){let d=state.live;if(supSurfWindow())return{label:'SUP-surf window · caution',title:d.angle==='Offshore'||d.angle==='Cross-offshore'?'Surfable lines—but the return wind is offshore':'A usable SUP-surf window may be forming',copy:`${d.wave.toFixed(1)} m at ${Math.round(d.period)} sec with ${Math.round(d.wind)} mph ${d.angle.toLowerCase()} wind fits the selected ${state.skill} hard-board SUP-surf profile. It is not an inflatable or flat-water recommendation.`,advice:'Stay within the break you can comfortably swim, check rip and tide movement, use a surf leash appropriate to the venue and keep a clear downwind exit.'};return v7Words(level)};

